/**
 * Determinism property tests for the reference store (Work Order A011
 * gate 11) — random legal open/append sequences through the store,
 * generated by a seeded LCG (test-support's StoreTestLcg; no new
 * dependencies, no Math.random, no wall-clock reads).
 *
 * Invariants:
 *   S1 every randomly-driven store trajectory passes full-chain
 *      verification and replay ordering;
 *   S2 store determinism — the same seed drives two independent stores
 *      to identical chain heads;
 *   S3 historical versions remain addressable by digest at every step
 *      (append-only storage);
 *   S4 every illegal append attempt at random points is rejected and
 *      leaves the stored state untouched;
 *   S5 idempotent replays of keyed appends never duplicate entries.
 */

import { describe, expect, it } from 'vitest';
import { verifyTrajectoryRecord } from '@arena/trajectory';
import { TRAJECTORY_ERROR_CODES } from '@arena/trajectory';
import { TrajectoryStore } from './store.js';
import type { CreateTrajectoryEntryInput } from '@arena/trajectory';
import { StoreTestLcg, makeStoreHeaderInput } from './test-support.js';

const SEEDS = [1, 42, 20260926, 777, 314159];
const BASE_MS = Date.parse('2026-03-01T12:00:00.000Z');

function randomInput(
  rng: StoreTestLcg,
  sequence: number,
  step: number,
  forceCompletion: boolean,
): CreateTrajectoryEntryInput {
  const occurredAt = new Date(BASE_MS + step * 250).toISOString();
  if (forceCompletion) {
    return {
      sequence,
      kind: 'completion',
      payload: {
        outcome: ['completed', 'failed', 'timed-out'][rng.int(3)] as string,
        evidenceDigests: rng.bool() ? [] : ['c'.repeat(64)],
      },
      occurredAt,
    };
  }
  switch (rng.int(4)) {
    case 0:
      return {
        sequence,
        kind: 'action',
        payload: { actionId: `action-${String(rng.int(6))}`, input: { step } },
        occurredAt,
      };
    case 1:
      return {
        sequence,
        kind: 'observation',
        payload: {
          observationId: `obs-${String(rng.int(6))}`,
          channel: ['stdout', 'stderr', 'metrics'][rng.int(3)] as string,
          content: `content ${String(step)}`,
        },
        occurredAt,
      };
    case 2:
      return {
        sequence,
        kind: 'error',
        payload: { code: `STORE_PROP_${String(rng.int(9))}`, message: `err ${String(step)}` },
        occurredAt,
      };
    default:
      return {
        sequence,
        kind: 'checkpoint',
        payload: { checkpointId: `cp-${String(rng.int(4))}`, snapshotDigest: 'd'.repeat(64) },
        occurredAt,
      };
  }
}

interface Walked {
  readonly chainHeads: readonly string[];
  readonly entryCounts: readonly number[];
}

async function drive(store: TrajectoryStore, seed: number, length: number): Promise<Walked> {
  const rng = new StoreTestLcg(seed);
  const trajectoryId = `trajectory-store-prop-${String(seed)}`;
  await store.open(
    makeStoreHeaderInput({ trajectoryId, startedAt: new Date(BASE_MS).toISOString() }),
  );
  const chainHeads: string[] = [];
  const entryCounts: number[] = [];
  const completionAt = 1 + rng.int(length);
  for (let step = 1; step <= length; step += 1) {
    const forceCompletion = step === completionAt;
    const receipt = await store.append(trajectoryId, randomInput(rng, step, step, forceCompletion));
    chainHeads.push(receipt.chainHead);
    entryCounts.push(receipt.record.entries.length);
    if (forceCompletion) break;
  }
  return { chainHeads, entryCounts };
}

describe('property: store chain integrity (S1)', () => {
  for (const seed of SEEDS) {
    it(`seed ${String(seed)}: stored trajectories verify and replay in order`, async () => {
      const store = new TrajectoryStore();
      const { chainHeads } = await drive(store, seed, 10);
      const latest = await store.getById(`trajectory-store-prop-${String(seed)}`);
      if (latest === undefined) throw new Error('walked trajectory must exist');
      await expect(verifyTrajectoryRecord(latest)).resolves.toBe(latest.chainHead);
      const stream = await store.replay(`trajectory-store-prop-${String(seed)}`);
      expect(stream.map((entry) => entry.sequence)).toEqual(
        stream.map((_, index) => index + 1),
      );
      expect(latest.chainHead).toBe(chainHeads[chainHeads.length - 1]);
    });
  }
});

describe('property: store determinism (S2)', () => {
  for (const seed of SEEDS) {
    it(`seed ${String(seed)}: two independent stores agree on every chain head`, async () => {
      const a = new TrajectoryStore();
      const b = new TrajectoryStore();
      const walkedA = await drive(a, seed, 8);
      const walkedB = await drive(b, seed, 8);
      expect(walkedA.chainHeads).toEqual(walkedB.chainHeads);
      expect(walkedA.entryCounts).toEqual(walkedB.entryCounts);
    });
  }
});

describe('property: historical versions stay addressable (S3)', () => {
  for (const seed of SEEDS.slice(0, 3)) {
    it(`seed ${String(seed)}: every intermediate chain head resolves to its version`, async () => {
      const store = new TrajectoryStore();
      const { chainHeads, entryCounts } = await drive(store, seed, 8);
      for (let index = 0; index < chainHeads.length; index += 1) {
        const chainHead = chainHeads[index];
        const expectedCount = entryCounts[index];
        if (chainHead === undefined || expectedCount === undefined) {
          throw new Error('unreachable: walked arrays are index-aligned');
        }
        const version = await store.getByDigest(chainHead);
        expect(version).toBeDefined();
        expect(version?.entries).toHaveLength(expectedCount);
      }
    });
  }
});

describe('property: illegal appends never mutate stored state (S4)', () => {
  for (const seed of SEEDS.slice(0, 3)) {
    it(`seed ${String(seed)}: random illegal attempts are rejected and stateless`, async () => {
      const store = new TrajectoryStore();
      const rng = new StoreTestLcg(seed * 31 + 2);
      const trajectoryId = `trajectory-illegal-${String(seed)}`;
      await store.open(makeStoreHeaderInput({ trajectoryId }));
      await store.append(trajectoryId, randomInput(rng, 1, 1, false));
      const before = await store.getById(trajectoryId);
      for (let attempt = 0; attempt < 10; attempt += 1) {
        const expected = (before?.entries.length ?? 0) + 1;
        const wrong = rng.bool() ? expected + 1 + rng.int(3) : 1 + rng.int(Math.max(1, expected - 1));
        await expect(
          store.append(trajectoryId, randomInput(rng, wrong, attempt + 2, false)),
        ).rejects.toThrowError(
          expect.objectContaining({
            code:
              wrong > expected
                ? TRAJECTORY_ERROR_CODES.SEQUENCE_GAP
                : TRAJECTORY_ERROR_CODES.SEQUENCE_REGRESSION,
          }),
        );
      }
      expect(await store.getById(trajectoryId)).toBe(before);
      expect(await store.list()).toHaveLength(1);
    });
  }
});

describe('property: keyed idempotent replays never duplicate (S5)', () => {
  for (const seed of SEEDS.slice(0, 3)) {
    it(`seed ${String(seed)}: replaying keyed appends is always a no-op`, async () => {
      const store = new TrajectoryStore();
      const rng = new StoreTestLcg(seed * 17 + 3);
      const trajectoryId = `trajectory-idem-${String(seed)}`;
      await store.open(makeStoreHeaderInput({ trajectoryId }));
      let entries = 0;
      for (let step = 1; step <= 6; step += 1) {
        const input = randomInput(rng, step, step, false);
        const key = `append-key-${String(seed)}-${String(step)}`;
        const firstReceipt = await store.append(trajectoryId, input, { idempotencyKey: key });
        void firstReceipt;
        entries += 1;
        // Random extra replays of earlier keys:
        if (rng.bool() && step > 1) {
          const earlierKey = `append-key-${String(seed)}-${String(1 + rng.int(step - 1))}`;
          const earlierSequence = 1 + rng.int(step - 1);
          const earlierInput = randomInput(rng, earlierSequence, earlierSequence, false);
          // The replay input must MATCH the original (same rng call order
          // would be needed to reproduce exactly), so expect either a
          // no-op or a typed conflict — never a duplicated entry.
          try {
            await store.append(trajectoryId, earlierInput, { idempotencyKey: earlierKey });
          } catch (error) {
            expect(error).toBeInstanceOf(Error);
          }
        }
        const replay = await store.append(trajectoryId, input, { idempotencyKey: key });
        expect(replay.record.entries).toHaveLength(entries); // never duplicated
      }
    });
  }
});
